CREATE TABLE public.league_match_rating_deltas (game_id uuid NOT NULL, player_key text NOT NULL, season integer NOT NULL, elo_delta numeric NOT NULL, won boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(game_id,player_key,season)); GRANT ALL ON public.league_match_rating_deltas TO service_role; ALTER TABLE public.league_match_rating_deltas ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.apply_league_match_ratings(p_game_id uuid,p_season integer,p_results jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_row jsonb; v_key text; BEGIN PERFORM pg_advisory_xact_lock(hashtext('admin-lobby-revert')); PERFORM 1 FROM games WHERE id=p_game_id AND is_league FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'League match not found'; END IF; IF jsonb_typeof(p_results)<>'array' OR jsonb_array_length(p_results)<2 THEN RAISE EXCEPTION 'At least two rating contributions required'; END IF; IF EXISTS(SELECT 1 FROM league_match_rating_deltas WHERE game_id=p_game_id) THEN RAISE EXCEPTION 'League ratings already applied for this match'; END IF; FOR v_row IN SELECT value FROM jsonb_array_elements(p_results) LOOP v_key:=lower(btrim(v_row->>'player_key')); IF v_key IS NULL OR NOT EXISTS(SELECT 1 FROM game_results WHERE game_id=p_game_id AND lower(btrim(player_name))=v_key) OR v_row->>'elo_delta' IS NULL THEN RAISE EXCEPTION 'Each contribution must match a seated result and include its Elo delta'; END IF; INSERT INTO league_match_rating_deltas(game_id,player_key,season,elo_delta,won) VALUES(p_game_id,v_key,p_season,(v_row->>'elo_delta')::numeric,coalesce((v_row->>'won')::boolean,false)); INSERT INTO player_league_ratings(player_key,season,elo,games_played,wins) VALUES(v_key,p_season,1000+(v_row->>'elo_delta')::numeric,1,CASE WHEN coalesce((v_row->>'won')::boolean,false) THEN 1 ELSE 0 END) ON CONFLICT(player_key,season) DO UPDATE SET elo=player_league_ratings.elo+(v_row->>'elo_delta')::numeric,games_played=player_league_ratings.games_played+1,wins=player_league_ratings.wins+CASE WHEN coalesce((v_row->>'won')::boolean,false) THEN 1 ELSE 0 END,updated_at=now(); END LOOP; RETURN jsonb_build_object('ok',true); END; $$; REVOKE ALL ON FUNCTION public.apply_league_match_ratings(uuid,integer,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.apply_league_match_ratings(uuid,integer,jsonb) TO service_role;
DO $$ DECLARE v_def text; BEGIN SELECT pg_get_functiondef('public.admin_revert_match_and_sp(bigint,uuid,boolean,boolean,uuid)'::regprocedure) INTO v_def; v_def:=replace(v_def,'v_result jsonb;','v_result jsonb; v_delta record;'); v_def:=replace(v_def,'AND r.games_played>0)', 'AND r.games_played>0 AND NOT EXISTS(SELECT 1 FROM league_match_rating_deltas d WHERE d.game_id=v_game AND d.player_key=r.player_key AND d.season=r.season))'); v_def:=replace(v_def,'PERFORM set_config(''request.jwt.claim.sub'',p_actor::text,true);', 'IF EXISTS(SELECT 1 FROM games g JOIN game_results gr ON gr.game_id=g.id JOIN player_league_ratings r ON r.player_key=lower(btrim(gr.player_name)) WHERE g.id=v_game AND g.is_league AND r.games_played>0 AND NOT EXISTS(SELECT 1 FROM league_match_rating_deltas d WHERE d.game_id=v_game AND d.player_key=r.player_key) AND NOT EXISTS(SELECT 1 FROM active_async_matches l WHERE l.linked_game_id=v_game AND coalesce(l.season_num,l.season_id) IS NOT NULL)) THEN RAISE EXCEPTION ''League season or per-match deltas missing. No changes were made''; END IF; FOR v_delta IN DELETE FROM league_match_rating_deltas WHERE game_id=v_game RETURNING * LOOP UPDATE player_league_ratings SET elo=elo-v_delta.elo_delta,games_played=greatest(0,games_played-1),wins=greatest(0,wins-CASE WHEN v_delta.won THEN 1 ELSE 0 END),updated_at=now() WHERE player_key=v_delta.player_key AND season=v_delta.season; END LOOP; PERFORM set_config(''request.jwt.claim.sub'',p_actor::text,true);'); EXECUTE v_def; END $$; REVOKE ALL ON FUNCTION public.admin_revert_match_and_sp(bigint,uuid,boolean,boolean,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.admin_revert_match_and_sp(bigint,uuid,boolean,boolean,uuid) TO service_role;